  r.findings.map((f) => ({ ...f, file: r.file }))
);
const verified = await Promise.all(findings.map((f) =>
  task({
    description: "Verify this finding: " + f.evidence,
    subagentType: "verifier",
  }).then((v) => ({ ...f, ...v }))
));
```

