//   const auditResults = await Promise.all(files.map(/* ...audit... */));

// A later eval — reference it; do NOT paste the findings back in as a literal:
const findings = auditResults.flatMap((r) =>
  r.findings.map((f) => ({ ...f, file: r.file }))
);
