const users = await tools.findUsers({ name: "Ada" });
const userId = users[0].id;
const [city, normalized] = await Promise.all([
  tools.cityForUser({ user_id: userId }),
  tools.normalize({ name: "Ada" }),
]);
console.log({ city, normalized });
```

